followupObserverMeasurement.reproductionScript:
import fs from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { performance } from 'node:perf_hooks';
const root = 'C:\\project\\CRDD';
const config = JSON.parse(fs.readFileSync(path.join(root, '.crdd/dogfooding/development-measurement-request.json'), 'utf8'));
const distribution = path.join(root, '.crdd/e2e-distributions', `development-${config.expectedCommit}`);
const packageModule = await import(pathToFileURL(path.join(distribution, 'tools/coordinator/src/security/platform-provisioner-package-filesystem.ts')).href);
const repositoryModule = await import(pathToFileURL(path.join(distribution, 'tools/coordinator/src/security/repository-operation-runtime.ts')).href);
const rows = [];
for (let sample = 1; sample <= 3; sample++) {
  for (const [observer, run] of [
    ['repository', () => repositoryModule.inspectRepositoryIdentityCandidate(root)],
    ['development_distribution', () => packageModule.inspectFixedDevelopmentCoordinatorPackageCandidate({ distributionRoot: distribution, expectedCrddTree: config.expectedTree, expectedPackageContentRootSha256: config.expectedPackageContentRootSha256 })],
    ['native_distribution', () => packageModule.inspectVerifiedNativeDistributionCandidate({ distributionRoot: config.nativeDistributionRoot, expectedRelease: config.expectedNativeRelease, evaluationTime: new Date().toISOString() })],
  ]) {
    const start = performance.now();
    const result = run();
    const row = { sample, observer, elapsedMs: performance.now() - start, accepted: observer === 'repository' ? result?.commit === config.expectedCommit && result?.tree === config.expectedTree : result?.status === 'candidate' };
    rows.push(row);
    process.stdout.write(`${JSON.stringify(row)}\n`);
  }
}
fs.writeFileSync(path.join(root, '.crdd/dogfooding/development-observer-profile-c95eb91.json'), JSON.stringify({ measuredAt: new Date().toISOString(), sourceCommit: config.expectedCommit, nodeVersion: process.version, providerInvoked: false, nativeProcessInvoked: false, rows }, null, 2) + '\n', { flag: 'wx' });
